/**
 * Market-aware API routing utility.
 * Routes requests to A股-specific or HK/US unified endpoints based on market.
 */

/**
 * Resolve the correct API endpoint for a given data view and market.
 * @param {string} view - The data view (e.g. 'review', 'realtime', 'monitor', 'positions', 'strategies', 'wave')
 * @param {string} market - The market code ('CN_A', 'HK', 'US')
 * @param {object} params - Optional query parameters
 * @returns {string} The resolved API URL
 */
export function marketApiUrl(view, market = 'CN_A', params = {}) {
  const m = (market || 'CN_A').toUpperCase();

  if (m === 'CN_A') {
    // A股 uses existing dedicated endpoints
    const routeMap = {
      review: '/api/market-review',
      realtime: '/api/market-review',
      monitor: '/api/ops/watchlist-with-leaders', // Hermes 选股监控池数据（含妙想持仓+监控股），非共享自选股
      positions: '/api/mock-trading/positions',
      strategies: '/api/ops/robot-strategies',
      'stock-analysis': '/api/ops/stock-analysis-latest',
      wave: '/api/ops/wave/signals',
      'wave-positions': '/api/ops/wave/positions',
      'wave-sectors': '/api/ops/wave/sector-summary',
      'concept-themes': '/api/ops/wave/concept-themes',
      'main-hub': '/api/main-hub/context',
    };
    const base = routeMap[view] || `/api/${view}`;
    const qs = new URLSearchParams(params).toString();
    return qs ? `${base}?${qs}` : base;
  }

  // HK/US uses unified endpoints
  const qs = new URLSearchParams(params).toString();
  const base = `/api/global-market/unified/${m}/${view}`;
  return qs ? `${base}?${qs}` : base;
}

/**
 * Check if the given market is A股 (CN_A).
 */
export function isCNA(market) {
  return (market || 'CN_A').toUpperCase() === 'CN_A';
}
