import { lazy, Suspense, useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import HeaderBar from '../components/cockpit/HeaderBar';
import CockpitSidebar from '../components/cockpit/CockpitSidebar';
import { useMainHubContext } from '../hooks/useMainHubContext';
import { useMarketReviewData } from '../hooks/useMarketReviewData';
import { marketApiUrl, isCNA } from '../lib/marketApi';
import { Zap, RefreshCw, AlertTriangle } from 'lucide-react';

// ===== 重型组件按需懒加载：把 recharts / framer-motion 拆出主 chunk，避免 414KB 单体包 =====
const MarketOverview = lazy(() => import('../components/cockpit/MarketOverview'));
const ThemeBattlefield = lazy(() => import('../components/cockpit/ThemeBattlefield'));
const FundFlowPanel = lazy(() => import('../components/cockpit/FundFlowPanel'));
const AllSectorsPanel = lazy(() => import('../components/cockpit/AllSectorsPanel'));

// ===== 骨架屏：在懒加载 chunk 到位前占位，避免布局抖动 =====
const MarketOverviewSkeleton = () => (
  <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
    {Array.from({ length: 8 }).map((_, i) => (
      <div key={i} className="h-20 rounded-xl bg-[var(--bg-surface)]/60 border border-[var(--border-color)] animate-pulse" />
    ))}
  </div>
);

const PanelSkeleton = ({ rows = 3, label = '加载中…' }) => (
  <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-surface)]/50 p-4 space-y-3">
    <div className="h-4 w-32 rounded bg-[var(--bg-surface)] animate-pulse" />
    {Array.from({ length: rows }).map((_, i) => (
      <div key={i} className="h-12 rounded-lg bg-[var(--bg-surface)] animate-pulse" />
    ))}
    <div className="text-xs text-[var(--text-secondary)]">{label}</div>
  </div>
);

const ThemeBattlefieldSkeleton = () => (
  <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
    {Array.from({ length: 3 }).map((_, i) => (
      <div key={i} className="h-48 rounded-xl bg-[var(--bg-surface)]/60 border border-[var(--border-color)] animate-pulse" />
    ))}
  </div>
);

const formatTimestamp = (value) => {
  if (!value) return '--';
  return String(value).replace('T', ' ').replace(/Z$/, '').replace(/\.[0-9]+$/, '').replace(/(\d{4})-(\d{2})-(\d{2})/, '$1/$2/$3');
};

export default function MarketToday({ shellMode, market = 'CN_A' } = {}) {
  const [selectedDate] = useState(() => new Date().toISOString().slice(0, 10));

  // 实时数据（15-30分钟刷新）
  // autoRefresh:false → 本页用下方单一 30s 定时器接管刷新，避免与 hook 内置 60s 定时器重复请求
  const {
    context: realtimeContext,
    loading: realtimeLoading,
    refreshing: realtimeRefreshing,
    updatedAt: realtimeUpdatedAt,
    syncContext,
    error: realtimeError,
  } = useMainHubContext({ market, autoRefresh: false });

  // 盘后资金流数据（19:00更新）
  const {
    review,
    loading: reviewLoading,
    refreshing: reviewRefreshing,
    updatedAt: reviewUpdatedAt,
    syncReview,
    error: reviewError,
  } = useMarketReviewData({ persistSelectedDate: false, market });

  // 刷新函数
  const refreshQuotes = () => {
    syncContext({ silent: true });
    syncReview({ silent: true });
  };

  const [activeNav, setActiveNav] = useState('nav-today');
  const navigate = useNavigate();

  // 自动刷新：每30秒刷新实时数据
  useEffect(() => {
    const timer = window.setInterval(() => {
      syncContext({ silent: true });
      syncReview({ silent: true });
    }, 30000);

    return () => window.clearInterval(timer);
  }, [syncContext, syncReview]);

  useEffect(() => {
    setActiveNav('nav-today');
  }, []);

  const navigateToItem = (item) => {
    setActiveNav(item.id);

    if (item.path) {
      navigate(item.path);
    }
  };

  // 实时主题数据
  const realTimeThemes = realtimeContext ? {
    mainline: realtimeContext.mainline || [],
    watch: realtimeContext.watch || [],
    alive: realtimeContext.alive || [],
  } : { mainline: [], watch: [], alive: [] };

  // 从 realtimeContext 获取市场数据
  const marketData = realtimeContext?.market || null;

  // 尝试获取实时指数（接口不可用时静默降级，不阻断页面渲染）
  const [indices, setIndices] = useState([]);
  const [indicesError, setIndicesError] = useState(false);
  useEffect(() => {
    let cancelled = false;
    const url = isCNA(market)
      ? '/api/realtime/indices'
      : marketApiUrl('realtime', market, { view: 'indices' });
    fetch(url)
      .then((r) => {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then((d) => {
        if (cancelled) return;
        if (d && Array.isArray(d.indices) && d.indices.length) {
          setIndices(d.indices);
          setIndicesError(false);
        } else {
          // 接口无数据 → 标记降级，下方用 market_metrics 兜底
          setIndicesError(true);
        }
      })
      .catch(() => {
        if (!cancelled) setIndicesError(true);
      });
    return () => { cancelled = true; };
  }, [market]);

  // 指数降级：API 无数据时，用 context.market_metrics 推导三大指数（有值才补）
  const derivedIndices = useMemo(() => {
    if (indices.length) return indices;
    const mm = realtimeContext?.market_metrics;
    if (!mm) return [];
    const candidates = [
      ['上证指数', mm.sh_index_change],
      ['深证成指', mm.sz_index_change],
      ['创业板指', mm.cyb_index_change],
    ];
    return candidates
      .filter(([, c]) => c != null && c !== undefined)
      .map(([name, c]) => ({
        name,
        price: null,
        change_pct: c,
        updated_at: mm.trade_date,
      }));
  }, [indices, realtimeContext]);

  const indicesDegraded = indicesError && derivedIndices.length === 0;

  // 获取板块排行数据 - 从mainline获取
  const sectorMatrix = realtimeContext?.sector_matrix || {};
  const sectorRankings = Array.isArray(sectorMatrix.mainline) ? sectorMatrix.mainline.slice(0, 10) : [];

  // 构建MarketOverview需要的数据格式
  const processedMarketData = marketData || {
    indices: derivedIndices.map(idx => ({
      name: idx.name,
      value: idx.price,
      change: idx.change_pct,
      trend: idx.change_pct >= 0 ? 'up' : 'down',
    })),
    limit_up: {
      limit_up: realtimeContext?.market_metrics?.limit_up_total || 0,
      broken: Math.round((realtimeContext?.market_metrics?.failed_bar_rate || 0) * 100),
    },
    heat: {
      value: realtimeContext?.market_metrics?.market_heat || 0,
      label: '',
      trend: 'neutral',
    },
    trade_date: derivedIndices[0]?.updated_at?.split(' ')[0] || '',
  };

  const isLoading = realtimeLoading || reviewLoading;
  const isRefreshing = realtimeRefreshing || reviewRefreshing;
  const latestUpdatedAt = realtimeUpdatedAt || reviewUpdatedAt;

  // 数据异常/空态横幅（实时或复盘接口失败时给出明确提示，而非静默空白）
  const dataBanners = (
    <>
      {realtimeError && (
        <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-red-50 border border-red-500/30 text-red-600 text-xs">
          <AlertTriangle className="h-4 w-4 shrink-0" />
          <span>实时数据获取失败：{realtimeError}</span>
        </div>
      )}
      {reviewError && (
        <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-red-50 border border-red-500/30 text-red-600 text-xs">
          <AlertTriangle className="h-4 w-4 shrink-0" />
          <span>复盘数据获取失败：{reviewError}</span>
        </div>
      )}
      {!realtimeContext && !realtimeLoading && (
        <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-amber-50 border border-amber-500/30 text-amber-700 text-xs">
          <AlertTriangle className="h-4 w-4 shrink-0" />
          <span>暂无实时数据，请稍后点击「刷新」重试。</span>
        </div>
      )}
    </>
  );

  if (shellMode) {
    return (
      <div className="space-y-3">
        {dataBanners}
        <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-emerald-50 border border-emerald-500/20">
          <Zap className="h-4 w-4 text-emerald-400" />
          <span className="text-xs text-emerald-600 font-medium">实时数据</span>
          <span className="text-xs text-[var(--text-secondary)]">更新: {formatTimestamp(realtimeUpdatedAt)}</span>
        </div>
        <Suspense fallback={<MarketOverviewSkeleton />}><MarketOverview data={processedMarketData} loading={realtimeLoading && derivedIndices.length === 0} sectorRankings={sectorRankings} /></Suspense>
        <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-surface)]/50 p-4">
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              <Zap className="h-4 w-4 text-cyan-400" />
              <span className="text-sm font-bold text-[var(--text-primary)]">板块行情</span>
              <span className="text-xs text-[var(--text-secondary)]">主线/观察/活跃</span>
            </div>
            <button onClick={refreshQuotes} className="flex items-center gap-1 text-xs text-[var(--text-secondary)] hover:text-[var(--text-secondary)]">
              <RefreshCw className="w-3 h-3" />
              刷新
            </button>
          </div>
          {realtimeLoading ? (
            <div className="flex items-center justify-center py-8">
              <RefreshCw className="w-5 h-5 text-cyan-400 animate-spin" />
            </div>
          ) : (
            <div className="space-y-4"><Suspense fallback={<PanelSkeleton rows={4} label="板块行情加载中…" />}><AllSectorsPanel /></Suspense></div>
          )}
          <div className="mt-2 text-xs text-[var(--text-secondary)]">更新时间: {formatTimestamp(realtimeUpdatedAt)}</div>
        </div>
        <Suspense fallback={<ThemeBattlefieldSkeleton />}><ThemeBattlefield themes={realTimeThemes} cognition={realtimeContext} loading={realtimeLoading} /></Suspense>
        <Suspense fallback={<PanelSkeleton rows={3} label="资金流向加载中…" />}><FundFlowPanel data={review?.fund_flow} themes={review?.themes} loading={reviewLoading} /></Suspense>
      </div>
    );
  }

  return (
    <div className="min-h-screen text-[var(--text-primary)]">
      <div className="mx-auto flex min-h-screen max-w-[1440px]">
        <CockpitSidebar
          collapsed={false}
          onToggleCollapsed={() => {}}
          activeNav={activeNav}
          updatedAt={latestUpdatedAt || '-'}
          status="实时"
          onNavigateItem={navigateToItem}
        />

        <main className="flex-1 overflow-y-auto scrollbar-thin">
          <div className="mx-auto w-full max-w-[1440px] px-3 py-3 lg:px-4">
            <HeaderBar
              date={selectedDate}
              onDateChange={() => {}}
              updatedAt={latestUpdatedAt || '-'}
              dataStatus="实时"
              resolvedDate={selectedDate}
              viewMode="LIVE"
              cognition={realtimeContext}
              onExportPdf={() => window.print()}
              onRefresh={() => {
                syncContext({ silent: true });
                syncReview({ silent: true });
              }}
              refreshing={isRefreshing}
              showDatePicker={false}
              titleOverride={`${selectedDate} 当日实时`}
              phaseTagOverride="自动刷新"
            />

            {dataBanners}

            <div className="mt-3 space-y-3">
              {/* === 实时数据区域 === */}
              <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-emerald-50 border border-emerald-500/20">
                <Zap className="h-4 w-4 text-emerald-400" />
                <span className="text-xs text-emerald-600 font-medium">实时数据</span>
                <span className="text-xs text-[var(--text-secondary)]">更新: {formatTimestamp(realtimeUpdatedAt)}</span>
              </div>

              <Suspense fallback={<MarketOverviewSkeleton />}><MarketOverview data={processedMarketData} loading={realtimeLoading && derivedIndices.length === 0} sectorRankings={sectorRankings} /></Suspense>
              {indicesDegraded && (
                <div className="text-xs text-[var(--text-secondary)] -mt-1">
                  指数行情暂不可用，已降级展示。
                </div>
              )}

              {/* === 板块实时行情 === */}
              <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-surface)]/50 p-4">
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-2">
                    <Zap className="h-4 w-4 text-cyan-400" />
                    <span className="text-sm font-bold text-[var(--text-primary)]">板块行情</span>
                    <span className="text-xs text-[var(--text-secondary)]">主线/观察/活跃</span>
                  </div>
                  <button
                    onClick={refreshQuotes}
                    className="flex items-center gap-1 text-xs text-[var(--text-secondary)] hover:text-[var(--text-secondary)]"
                  >
                    <RefreshCw className={`w-3 h-3`} />
                    刷新
                  </button>
                </div>

                {realtimeLoading ? (
                  <div className="flex items-center justify-center py-8">
                    <RefreshCw className="w-5 h-5 text-cyan-400 animate-spin" />
                  </div>
                ) : (
                  <div className="space-y-4">
                    {/* 全部板块 */}
                    <Suspense fallback={<PanelSkeleton rows={4} label="板块行情加载中…" />}><AllSectorsPanel /></Suspense>
                  </div>
                )}

                <div className="mt-2 text-xs text-[var(--text-secondary)]">
                  更新时间: {formatTimestamp(realtimeUpdatedAt)}
                </div>
              </div>

              <Suspense fallback={<ThemeBattlefieldSkeleton />}><ThemeBattlefield themes={realTimeThemes} cognition={realtimeContext} loading={realtimeLoading} /></Suspense>

              {/* === 资金流向 === */}
              <Suspense fallback={<PanelSkeleton rows={3} label="资金流向加载中…" />}><FundFlowPanel
                data={review?.fund_flow}
                themes={review?.themes}
                loading={reviewLoading}
              /></Suspense>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}
