export const EMPTY_ROTATION = createEmptyRotation();
export const EMPTY_MAIN_HUB = createEmptyMainHub();
export const EMPTY_REVIEW = createEmptyReview();

export function mergeDeep(base, incoming) {
  if (incoming === undefined) {
    return cloneValue(base);
  }

  if (Array.isArray(incoming)) {
    return incoming.map((item) => cloneValue(item));
  }

  if (!isPlainObject(base) || !isPlainObject(incoming)) {
    return cloneValue(incoming);
  }

  const output = cloneValue(base);
  for (const [key, value] of Object.entries(incoming)) {
    if (isPlainObject(value) && isPlainObject(base[key])) {
      output[key] = mergeDeep(base[key], value);
    } else {
      output[key] = cloneValue(value);
    }
  }

  return output;
}

export function normalizeMainHubPayload(payload = {}) {
  const hub = mergeDeep(EMPTY_MAIN_HUB, payload);
  const sourceRotation = payload?.market_context?.rotation || payload?.rotation || {};
  hub.market_context.rotation = mergeDeep(EMPTY_ROTATION, hub.market_context.rotation || sourceRotation);

  if (!hub.market_context.mainline.length && Array.isArray(payload?.mainline)) {
    hub.market_context.mainline = cloneValue(payload.mainline);
  }
  if (!hub.market_context.watch.length && Array.isArray(payload?.watch)) {
    hub.market_context.watch = cloneValue(payload.watch);
  }
  if (!hub.market_context.alive.length && Array.isArray(payload?.alive)) {
    hub.market_context.alive = cloneValue(payload.alive);
  }

  return hub;
}

export function normalizeReviewPayload(payload = {}) {
  const review = mergeDeep(EMPTY_REVIEW, payload);
  const sourceRotation = review.rotation || review.main_hub?.market_context?.rotation || {};
  review.rotation = mergeDeep(EMPTY_ROTATION, sourceRotation);
  review.main_hub = normalizeMainHubPayload(review.main_hub || payload?.main_hub || {});
  review.main_hub.market_context.rotation = mergeDeep(
    EMPTY_ROTATION,
    review.main_hub.market_context.rotation || review.rotation,
  );

  if (!review.cognition.stage && review.main_hub?.market_context) {
    const context = review.main_hub.market_context;
    review.cognition = mergeDeep(EMPTY_REVIEW.cognition, {
      stage: context.stage || '',
      stage_score: context.stage_score ?? 0,
      stage_description: context.stage_description || '',
      mainline: Array.isArray(context.mainline) ? context.mainline : [],
      watch: Array.isArray(context.watch) ? context.watch : [],
      risk_level: context.risk_level || '',
      warnings: Array.isArray(review.risk_warning) ? review.risk_warning : [],
      signals: context.signals || { stage: [], theme: [], risk: [] },
      position: context.position_suggestion || '',
      updated_at: context.updated_at || review.updated_at || '',
      source: context.source || review.main_hub?.data_source?.input_mode || '',
      breakdown: context.breakdown || EMPTY_REVIEW.cognition.breakdown,
    });
  } else {
    review.cognition = mergeDeep(EMPTY_REVIEW.cognition, review.cognition || {});
  }

  review.updated_at =
    review.updated_at ||
    review.meta?.updated_at ||
    review.main_hub?.meta?.created_at ||
    review.main_hub?.data_source?.updated_at ||
    '';

  if (!review.main_hub.market_context.updated_at) {
    review.main_hub.market_context.updated_at = review.updated_at;
  }

  return review;
}
