import { useMemo } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import {
  Zap,
  LayoutDashboard,
  Flame,
  Globe,
  Gauge,
  Trophy,
  Layers,
  Bot,
  Terminal,
  TrendingUp,
  Target,
  Clock,
  CandlestickChart,
  FileText,
  CalendarDays,
  Activity,
  DollarSign,
  Landmark,
  Compass,
  Network,
} from 'lucide-react';

const DEFAULT_INLINE_NAVIGATION_ITEM_IDS = [
  'stock_monitor',
  'stock_analysis',
  'robot_strategies',
  'strategy_position',
];

const TIMELINE_MENU = [
  {
    key: 'trading_phase',
    title: 'A股·盘中',
    icon: <Activity className="w-4 h-4 text-[var(--text-muted)]" />,
    isLive: true,
    items: [
      { id: 'mkt_realtime', label: '今日实时', icon: Activity, path: '/today' },
    ]
  },
  {
    key: 'review_phase',
    title: 'A股·复盘',
    icon: <LayoutDashboard className="w-4 h-4 text-[var(--text-muted)]" />,
    items: [
      { id: 'mkt_summary', label: '复盘总览', icon: LayoutDashboard, path: '/' },
      { id: 'theme_track', label: '题材复盘', icon: Flame, path: '/theme-review' },
      { id: 'consolidated', label: '综合数据', icon: Compass, path: '/emotion' },
    ]
  },
  {
    key: 'robot_phase',
    title: 'A股·策略',
    icon: <Bot className="w-4 h-4 text-[var(--text-muted)]" />,
    items: [
      { id: 'stock_monitor', label: '选股持仓', icon: Target, path: '/stock-monitor' },
      { id: 'stock_analysis', label: '选股分析', icon: Zap, path: '/stock-analysis' },
      { id: 'robot_strategies', label: '策略信号', icon: Zap, path: '/robot-strategies' },
      { id: 'strategy_position', label: '波段信号', icon: Activity, path: '/strategy-position' },
    ]
  },
  {
    key: 'global_phase',
    title: '全球市场',
    icon: <Globe className="w-4 h-4 text-[var(--text-muted)]" />,
    items: [
      { id: 'hk_market', label: '港股市场', icon: Landmark, path: '/hk-market' },
      { id: 'us_market', label: '美股市场', icon: DollarSign, path: '/us-market' },
    ]
  }
];

export default function CockpitSidebar({
  currentView,
  onViewChange,
  collapsed,
  onToggleCollapsed,
  activeNav,
  updatedAt,
  status,
  onNavigateItem,
  inlineNavigationItemIds = [],
  inlineNavigationTarget = '/robot-strategies',
}) {
  const location = useLocation();
  const navigate = useNavigate();
  const inlineNavigationSet = useMemo(
    () => new Set([...DEFAULT_INLINE_NAVIGATION_ITEM_IDS, ...inlineNavigationItemIds]),
    [inlineNavigationItemIds]
  );
  const pathToItemId = useMemo(() => {
    const mapping = {};
    for (const group of TIMELINE_MENU) {
      for (const item of group.items || []) {
        if (item.path) {
          mapping[item.path] = item.id;
        }
      }
    }
    mapping['/theme-review'] = 'theme_track';
    mapping['/theme-track'] = 'theme_track';
    return mapping;
  }, []);
  const routeActiveId = inlineNavigationSet.size > 0 && location.pathname === inlineNavigationTarget
    ? ''
    : pathToItemId[location.pathname] || '';

  const navigateToItem = (item) => {
    const isInlineItem = inlineNavigationSet.has(item.id);
    if (isInlineItem) {
      if (location.pathname !== inlineNavigationTarget) {
        navigate(inlineNavigationTarget, { state: { activeSection: item.id } });
      }
    } else if (item.path && location.pathname !== item.path) {
      navigate(item.path);
    }
    if (onViewChange) {
      onViewChange(item.id);
    }
    if (onNavigateItem) {
      onNavigateItem(item);
    }
  };

  return (
    <>
      <div className={`
        fixed inset-y-0 left-0 z-40 w-44 border-r border-[var(--border-color)]
        bg-[var(--bg-card)] p-2
        md:static
      `}>
        <div className="mb-6 flex items-center justify-between px-2 border-b border-[var(--border-light)] pb-4">
          <div className="flex items-center space-x-3">
            <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[var(--bg-surface)] border border-[var(--border-color)] font-mono text-sm font-black text-[var(--text-secondary)]">
              Ω
            </div>
            <div>
              <h1 className="font-mono text-[13px] font-bold tracking-widest text-[var(--text-primary)] uppercase">Hermes</h1>
              <p className="text-[10px] font-semibold tracking-wider text-[var(--text-muted)]">Workstation</p>
            </div>
          </div>
        </div>

        <nav className="space-y-4 h-[calc(100vh-150px)] overflow-y-auto pr-1 scrollbar-thin scrollbar-thumb-gray-200">
          {TIMELINE_MENU.map((group) => {
            return (
              <div key={group.key} className="space-y-1">
                <div className="flex w-full items-center justify-between rounded-lg px-2.5 py-2 text-left">
                  <div className="flex items-center space-x-2.5">
                    <div className="relative">
                      {group.icon}
                      {group.isLive && (
                        <span className="absolute -top-1 -right-1 flex h-1.5 w-1.5">
                          <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                          <span className="relative inline-flex rounded-full h-1.5 w-1.5 bg-red-500"></span>
                        </span>
                      )}
                    </div>
                    <div>
                      <span className="block text-base font-semibold tracking-wide text-[var(--text-secondary)]">{group.title}</span>
                    </div>
                  </div>
                </div>

                {(
                  <div className="space-y-0.5 pl-2 border-l border-[var(--border-light)] ml-4.5 mt-0.5">
                    {group.items.map((item) => {
                      const IconComponent = item.icon;
                      const isActive = (routeActiveId === item.id) || (currentView === item.id) || (activeNav === item.id);

                      if (item.external) {
                        return (
                          <a
                            key={item.id}
                            href={item.href}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="w-full flex items-center space-x-3 rounded-lg px-3 py-2.5 text-left transition-all duration-150 bg-[var(--bg-surface)] border border-[var(--border-light)] hover:border-[var(--border-color)] hover:bg-[var(--bg-hover)]"
                          >
                            <IconComponent className="w-4 h-4 text-[var(--text-muted)]" />
                            <span className="text-[14px] font-medium text-[var(--text-secondary)]">API 网关</span>
                            <span className="ml-auto text-[10px] font-bold tracking-wider text-[var(--text-muted)] uppercase">↗</span>
                          </a>
                        );
                      }

                      return (
                        <button
                          key={item.id}
                          onClick={() => navigateToItem(item)}
                          className={`
                            w-full flex items-center justify-between rounded-lg px-3 py-2.5 text-left transition-all duration-150
                            ${isActive
                              ? 'bg-[var(--bg-surface)] border border-[var(--border-color)] text-[var(--text-primary)]'
                              : 'text-[var(--text-muted)] hover:bg-[var(--bg-surface)] hover:text-[var(--text-secondary)]'
                            }
                          `}
                        >
                          <div className="flex items-center space-x-3">
                            <IconComponent className={`w-4 h-4 ${isActive ? 'text-blue-500' : 'text-[var(--text-muted)]'}`} />
                            <span className="text-[14px] font-medium text-[var(--text-secondary)]">{item.label}</span>
                          </div>
                          {item.badge && (
                            <span className="rounded bg-[var(--bg-hover)] px-2 py-0.5 text-[10px] font-medium text-[var(--text-secondary)]">
                              {item.badge}
                            </span>
                          )}
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          })}
        </nav>
      </div>
    </>
  );
}
