import { motion } from 'framer-motion';
import { Download, RefreshCw, CalendarDays, Sun, Moon } from 'lucide-react';
import { useState, useEffect } from 'react';
import { getTodayDateString } from '../../lib/marketReviewShape';

const THEME_STORAGE_KEY = 'hermes_theme';

const STATUS_STYLE = {
  最新: 'bg-green-50 text-green-600 border-green-200',
  延迟: 'bg-yellow-50 text-yellow-600 border-yellow-200',
  缺失: 'bg-red-50 text-red-600 border-red-200',
};

const RISK_STYLE = {
  低: 'border-green-200 bg-green-50 text-green-600',
  中: 'border-yellow-200 bg-yellow-50 text-yellow-600',
  高: 'border-red-200 bg-red-50 text-red-600',
  极高: 'border-red-200 bg-red-50 text-red-600',
};

const STAGE_STYLE = {
  冰点: 'border-[var(--border-color)] bg-[var(--bg-surface)] text-[var(--text-secondary)]',
  修复: 'border-[var(--border-color)] bg-[var(--bg-surface)] text-[var(--text-secondary)]',
  发酵: 'border-green-200 bg-green-50 text-green-600',
  高潮: 'border-[var(--border-color)] bg-[var(--bg-surface)] text-[var(--text-secondary)]',
  分歧: 'border-[var(--border-color)] bg-[var(--bg-surface)] text-[var(--text-secondary)]',
  退潮: 'border-red-200 bg-red-50 text-red-600',
};

function toDateString(value) {
  if (!value) return '';
  const text = String(value).trim();
  if (!text) return '';
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) return text;
  const m = text.match(/^(\d{4}-\d{2}-\d{2})/);
  return m ? m[1] : '';
}

function formatLocalDate(dateObj) {
  const pad = (value) => String(value).padStart(2, '0');
  return `${dateObj.getFullYear()}-${pad(dateObj.getMonth() + 1)}-${pad(dateObj.getDate())}`;
}

function formatTimestampDisplay(value) {
  if (value === null || value === undefined || value === '') return '-';
  const text = String(value).trim();
  if (!text) return '-';
  return text
    .replace('T', ' ')
    .replace(/Z$/, '')
    .replace(/(\d{4})-(\d{2})-(\d{2})/, '$1/$2/$3')
    .replace(/(\d{2}:\d{2}:\d{2})\.\d+(?=(?:[+-]\d{2}:?\d{2})?$)/, '$1')
    .replace(/[+-]\d{2}:?\d{2}$/, '')
    .trim();
}

function previousTradingDate(baseDateString) {
  const source = toDateString(baseDateString) || getTodayDateString();
  const [year, month, day] = source.split('-').map((item) => Number(item));
  const date = new Date(year, (month || 1) - 1, day || 1);
  for (let i = 0; i < 7; i += 1) {
    date.setDate(date.getDate() - 1);
    const day = date.getDay();
    if (day !== 0 && day !== 6) {
      return formatLocalDate(date);
    }
  }
  return source;
}

function deriveReviewHeader({ selectedDate, resolvedDate, updatedAt, dataStatus }) {
  const now = new Date();
  const today = getTodayDateString();
  const selected = toDateString(selectedDate) || today;
  const resolved = toDateString(resolvedDate);
  const updated = toDateString(updatedAt);
  const hasTodayData = resolved === selected || updated === selected;
  const isTodayQuery = selected === today;
  const beforeOpen = now.getHours() < 9 || (now.getHours() === 9 && now.getMinutes() < 30);

  if (!isTodayQuery) {
    return { title: `${selected} 盘后复盘`, phaseTag: '历史盘后' };
  }

  if (hasTodayData && dataStatus === '最新') {
    return { title: `${selected} 盘后复盘`, phaseTag: '已收盘' };
  }

  if (beforeOpen) {
    return { title: `${selected} 盘前`, phaseTag: '盘前' };
  }

  const fallbackDate = resolved || updated || previousTradingDate(selected);
  return { title: `${fallbackDate} 盘后数据`, phaseTag: '上一交易日盘后' };
}

export default function HeaderBar({
  date,
  onDateChange,
  updatedAt,
  dataStatus,
  resolvedDate,
  viewMode,
  cognition,
  onExportPdf,
  onRefresh,
  refreshing = false,
  showDatePicker = true,
  titleOverride = '',
  phaseTagOverride = '',
  statusIndicator = null, // 子组件传入的实时状态指示
}) {
  const statusClass = STATUS_STYLE[dataStatus] || STATUS_STYLE.缺失;
  const stageClass = STAGE_STYLE[cognition?.stage] || 'border-[var(--border-color)] bg-[var(--bg-hover)] text-[var(--text-secondary)]';
  const riskClass = RISK_STYLE[cognition?.risk_level] || 'border-[var(--border-color)] bg-[var(--bg-hover)] text-[var(--text-secondary)]';
  const mainlineCount = Array.isArray(cognition?.mainline) ? cognition.mainline.length : 0;
  const watchCount = Array.isArray(cognition?.watch) ? cognition.watch.length : 0;
  const derived = deriveReviewHeader({
    selectedDate: date,
    resolvedDate,
    updatedAt,
    dataStatus,
  });
  const title = titleOverride || derived.title;
  const phaseTag = phaseTagOverride || derived.phaseTag;
  const [theme, setTheme] = useState(() => {
    if (typeof window === 'undefined') return 'dark';
    const stored = window.localStorage.getItem(THEME_STORAGE_KEY);
    return stored === 'light' || stored === 'dark' ? stored : 'dark';
  });

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    if (typeof window !== 'undefined') {
      window.localStorage.setItem(THEME_STORAGE_KEY, theme);
    }
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  return (
    <motion.header
      initial={{ opacity: 0, y: -10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.35 }}
      className="glass-card rounded-[24px] px-4 py-3.5"
    >
      <div className="flex flex-col gap-3 xl:flex-row xl:items-end xl:justify-between">
        <div className="space-y-2">
          <div className="text-xs font-semibold tracking-[0.34em] text-[var(--text-muted)]">HERMES MARKET REVIEW</div>
          <div className="text-[28px] font-bold leading-none text-[var(--text-primary)]">
            {title || '盘后复盘'}
          </div>
          <div className="text-sm text-[var(--text-muted)]">Hermes Market Review Cockpit</div>
          <div className="flex flex-wrap items-center gap-2.5 text-sm text-[var(--text-muted)]">
            <span className={`rounded-full border px-3 py-1 text-xs font-semibold ${statusClass}`}>{dataStatus || '缺失'}</span>
            <span className="inline-flex items-center gap-2 rounded-full border border-[var(--border-color)] bg-[var(--bg-surface)] px-3 py-1 text-xs text-[var(--text-secondary)]">
              <CalendarDays className="h-4 w-4 text-[var(--text-muted)]" />
              <span className="font-mono">{formatTimestampDisplay(updatedAt)}</span>
            </span>
            <span className="rounded-full border border-[var(--border-color)] bg-[var(--bg-surface)] px-3 py-1 text-xs text-[var(--text-secondary)]">
              {phaseTag}
            </span>
            <span className="rounded-full border border-blue-200 bg-blue-50 px-3 py-1 text-xs text-blue-600">
              {viewMode === 'HISTORY' ? '历史复盘模式' : '实时模式'}
            </span>
          </div>
          {cognition ? (
            <div className="flex flex-wrap items-center gap-2 pt-1 text-xs">
              <span className={`rounded-full border px-3 py-1 font-semibold ${stageClass}`}>
                阶段 {cognition.stage || '未识别'}
              </span>
              <span className={`rounded-full border px-3 py-1 font-semibold ${riskClass}`}>
                风险 {cognition.risk_level || '未知'}
              </span>
              <span className="rounded-full border border-[var(--border-color)] bg-[var(--bg-surface)] px-3 py-1 font-semibold text-[var(--text-secondary)]">
                主线 {mainlineCount}
              </span>
              <span className="rounded-full border border-[var(--border-color)] bg-[var(--bg-surface)] px-3 py-1 font-semibold text-[var(--text-secondary)]">
                观察 {watchCount}
              </span>
              <span className="rounded-full border border-[var(--border-color)] bg-[var(--bg-surface)] px-3 py-1 font-semibold text-[var(--text-muted)]">
                仓位 {cognition.position || '-'}
              </span>
            </div>
          ) : null}
          {statusIndicator}
        </div>

        <div className="flex flex-wrap gap-2 sm:flex-nowrap sm:items-center">
          {showDatePicker ? (
            <label className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-surface)] px-3 py-2.5 text-sm text-[var(--text-secondary)]">
              <div className="mb-1 text-[11px] uppercase tracking-[0.18em] text-[var(--text-muted)]">Review Date</div>
              <input
                type="date"
                value={date}
                onChange={(event) => onDateChange(event.target.value)}
                className="w-full bg-transparent font-medium text-[var(--text-primary)] outline-none"
              />
            </label>
          ) : null}

          <button
            type="button"
            onClick={onRefresh}
            disabled={refreshing}
            className="inline-flex items-center justify-center gap-2 rounded-2xl border border-blue-200 bg-blue-50 px-3.5 py-2.5 text-sm font-medium text-blue-600 transition hover:bg-blue-100 disabled:cursor-not-allowed disabled:opacity-70"
          >
            <RefreshCw className={`h-4 w-4 ${refreshing ? 'animate-spin' : ''}`} />
            {refreshing ? '执行中...' : '刷新数据'}
          </button>

          <button
            type="button"
            onClick={onExportPdf}
            className="inline-flex items-center justify-center gap-2 rounded-2xl border border-blue-200 bg-blue-50 px-3.5 py-2.5 text-sm font-medium text-blue-600 transition hover:bg-blue-100"
          >
            <Download className="h-4 w-4" />
            导出 PDF
          </button>

          <button
            type="button"
            onClick={toggleTheme}
            className="inline-flex items-center justify-center gap-2 rounded-2xl border border-[var(--border-color)] bg-[var(--bg-surface)] px-3.5 py-2.5 text-sm font-medium text-[var(--text-secondary)] transition hover:bg-[var(--bg-hover)]"
          >
            {theme === 'dark' ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}
            {theme === 'dark' ? '明亮' : '暗黑'}
          </button>
        </div>
      </div>
    </motion.header>
  );
}
