import { useEffect, useRef, useState } from 'react';
import {
  EMPTY_MAIN_HUB,
  EMPTY_REVIEW,
  getLocalDateString,
  getTodayDateString,
  normalizeReviewPayload,
} from '../lib/marketReviewShape';
import { fetchJson } from '../lib/http';
import { marketApiUrl, isCNA } from '../lib/marketApi';

const REVIEW_DATE_STORAGE_KEY = 'hermes.review.selected-date';

export { EMPTY_REVIEW } from '../lib/marketReviewShape';

export function useMarketReviewData({ persistSelectedDate = true, market = 'CN_A' } = {}) {
  const [selectedDate, setSelectedDate] = useState(() => {
    if (persistSelectedDate && typeof window !== 'undefined') {
      const stored = window.sessionStorage.getItem(REVIEW_DATE_STORAGE_KEY);
      if (stored) return stored;
    }
    return getLocalDateString();
  });
  const [review, setReview] = useState(() => EMPTY_REVIEW);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState('');
  const [updatedAt, setUpdatedAt] = useState('');
  const [mainHub, setMainHub] = useState(() => EMPTY_MAIN_HUB);
  const requestControllerRef = useRef(null);

  useEffect(() => {
    if (persistSelectedDate && typeof window !== 'undefined') {
      window.sessionStorage.setItem(REVIEW_DATE_STORAGE_KEY, selectedDate);
    }
  }, [persistSelectedDate, selectedDate]);

  const fetchReview = async (date, signal) => {
    if (isCNA(market)) {
      return fetchJson(`/api/market-review?date=${encodeURIComponent(date)}`, {
        signal,
        timeoutMs: 15000,
      });
    }
    // HK/US: use unified review endpoint
    return fetchJson(marketApiUrl('review', market, { date }), {
      signal,
      timeoutMs: 15000,
    });
  };

  const syncReview = async ({ silent = false } = {}) => {
    if (requestControllerRef.current) {
      requestControllerRef.current.abort();
    }
    const controller = new AbortController();
    requestControllerRef.current = controller;

    try {
      if (!silent) {
        setLoading(true);
        setError('');
      } else {
        setRefreshing(true);
      }

      const data = await fetchReview(selectedDate, controller.signal);
      if (controller.signal.aborted) return;

      const normalized = normalizeReviewPayload(data);

      setReview(normalized);
      setMainHub(normalized.main_hub || EMPTY_MAIN_HUB);
      setUpdatedAt(
        normalized.updated_at ||
        normalized.meta?.updated_at ||
        normalized.main_hub?.meta?.created_at ||
        normalized.main_hub?.data_source?.updated_at ||
        new Date().toLocaleString(),
      );
    } catch (errorValue) {
      if (errorValue?.name === 'AbortError') {
        return;
      }
      setError('无法获取市场复盘数据，请确认 FastAPI 服务可用（接口超时或异常）。');
      if (!silent) {
        setReview(EMPTY_REVIEW);
        setMainHub(EMPTY_MAIN_HUB);
      }
    } finally {
      if (requestControllerRef.current === controller) {
        requestControllerRef.current = null;
      }
      if (!controller.signal.aborted) {
        setLoading(false);
        setRefreshing(false);
      }
    }
  };

  useEffect(() => {
    syncReview();
    return () => {
      if (requestControllerRef.current) {
        requestControllerRef.current.abort();
        requestControllerRef.current = null;
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDate, market]);

  const viewMode = selectedDate === getTodayDateString() ? 'LIVE' : 'HISTORY';

  return {
    error,
    loading,
    refreshing,
    review,
    selectedDate,
    setSelectedDate,
    setReview,
    syncReview,
    updatedAt,
    mainHub,
    viewMode,
    cognition: review.cognition || EMPTY_REVIEW.cognition,
  };
}
