import { useEffect, useRef, useState } from 'react';
import { getLocalDateString } from '../lib/marketReviewShape';
import { fetchJson } from '../lib/http';
import { marketApiUrl, isCNA } from '../lib/marketApi';

export function useMainHubContext({ market = 'CN_A', autoRefresh = true } = {}) {
  const [selectedDate, setSelectedDate] = useState(() => getLocalDateString());
  const [context, setContext] = useState(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState('');
  const [updatedAt, setUpdatedAt] = useState('');
  const requestControllerRef = useRef(null);

  const syncContext = async ({ silent = false } = {}) => {
    if (requestControllerRef.current) {
      requestControllerRef.current.abort();
    }
    const controller = new AbortController();
    requestControllerRef.current = controller;

    try {
      if (!silent) {
        setLoading(true);
        setError('');
      } else {
        setRefreshing(true);
      }

      const url = isCNA(market)
        ? `/api/main-hub/context?date=${encodeURIComponent(selectedDate)}`
        : marketApiUrl('realtime', market);

      const data = await fetchJson(url, {
        signal: controller.signal,
        timeoutMs: 15000,
      });
      if (controller.signal.aborted) return;

      setContext(data);
      setUpdatedAt(data.updated_at || new Date().toLocaleString());
    } catch (errorValue) {
      if (errorValue?.name === 'AbortError') {
        return;
      }
      setError('无法获取实时数据（接口超时或异常）');
    } finally {
      if (requestControllerRef.current === controller) {
        requestControllerRef.current = null;
      }
      if (!controller.signal.aborted) {
        setLoading(false);
        setRefreshing(false);
      }
    }
  };

  useEffect(() => {
    syncContext();
    return () => {
      if (requestControllerRef.current) {
        requestControllerRef.current.abort();
        requestControllerRef.current = null;
      }
    };
  }, [selectedDate, market]);

  // 自动刷新：每 60 秒更新一次（盘中实时数据）
  // autoRefresh=false 时由调用方（如 MarketToday）自行接管定时器，避免重复刷新
  useEffect(() => {
    if (!autoRefresh) return;
    const interval = setInterval(() => {
      syncContext({ silent: true });
    }, 60000); // 60 秒刷新

    return () => clearInterval(interval);
  }, []);

  return {
    error,
    loading,
    refreshing,
    context,
    selectedDate,
    setSelectedDate,
    syncContext,
    updatedAt,
  };
}
